**GW-BASIC Program (2017 Exam):**
```basic
10 CLS
20 SUM = 0 : MAX = 0
30 DIM W(55)
40 FOR I = 1 TO 55
50 INPUT "Enter weight of club member: "; W(I)
60 SUM = SUM + W(I)
70 IF W(I) > MAX THEN MAX = W(I)
80 NEXT I
90 AVG = SUM / 55
100 PRINT "Average Weight = "; AVG
110 PRINT "Maximum Weight = "; MAX
120 END
```

**2025 Syllabus Equivalent (JavaScript — SLO `10.6.4`):**
```javascript
let W = new Array(55);
let sum = 0;
let max = -Infinity;
for (let i = 0; i < 55; i++) {
    W[i] = parseFloat(prompt("Enter weight of member " + (i + 1) + ":"));
    sum += W[i];
    if (W[i] > max) {
        max = W[i];
    }
}
let avg = sum / 55;
document.write("Average Weight: " + avg + "<br>");
document.write("Maximum Weight: " + max);
```

**GW-BASIC Program (2017 Exam):**
```basic
10 CLS
20 INPUT "Enter weight in kg: "; W
30 INPUT "Enter height in metres: "; H
40 BMI = W / (H ^ 2)
50 IF BMI >= 27.5 THEN PRINT "Obese"
60 IF BMI >= 23 AND BMI <= 27.4 THEN PRINT "Overweight"
70 IF BMI >= 18.5 AND BMI <= 22.9 THEN PRINT "Healthy"
80 IF BMI < 18.5 THEN PRINT "Underweight"
90 END
```

**2025 Syllabus Equivalent (JavaScript):**
```javascript
let W = parseFloat(prompt("Enter weight in kg (W):"));
let H = parseFloat(prompt("Enter height in metres (H):"));
let bmi = W / (H * H);
if (bmi >= 27.5) {
    document.write("Obese");
} else if (bmi >= 23 && bmi <= 27.4) {
    document.write("Overweight");
} else if (bmi >= 18.5 && bmi <= 22.9) {
    document.write("Healthy");
} else {
    document.write("Underweight");
}
```
